[data-placeholder] { max-width: 36rem; margin: 0px auto; text-align: center; }[data-placeholder] h1 { font-style: normal; font-variant-caps: normal; font-weight: 900; font-width: normal; font-size: 3rem; line-height: 1.05; font-family: system-ui, sans-serif; font-size-adjust: none; font-kerning: auto; font-variant-alternates: normal; font-variant-ligatures: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-position: normal; font-variant-emoji: normal; font-feature-settings: normal; font-optical-sizing: auto; font-variation-settings: normal; letter-spacing: -0.02em; margin: 0px 0px 0.25rem; }[data-placeholder] h1 .wave { display: inline-block; transform-origin: 70% 70%; animation: 1.6s infinite ph-wave; }@keyframes ph-wave { 
  0%,100% { transform: rotate(0deg); }
  25% { transform: rotate(20deg); }
  75% { transform: rotate(-10deg); }
}[data-placeholder] .ph-lead { font-size: 1.25rem; margin: 1rem 0px 1.5rem; line-height: 1.4; }[data-placeholder] footer { margin-top: 1.5rem; opacity: 0.55; font-size: 0.9rem; }[data-placeholder] .ph-arrow { position: fixed; right: 1rem; bottom: 1rem; width: clamp(140px, 38vw, 220px); pointer-events: none; z-index: 9; transform-origin: 90% 90%; animation: 1.8s ease-in-out infinite ph-arrow-bob; }[data-placeholder] .ph-arrow.is-dismissed { animation: 0.4s ease-in forwards ph-arrow-out; }[data-placeholder] .ph-arrow svg { display: block; width: 100%; height: auto; overflow: visible; }[data-placeholder] .ph-arrow .ph-arrow-stroke { stroke-dasharray: 320; stroke-dashoffset: 320; animation: 1.6s ease-out 0.2s forwards ph-arrow-draw; }[data-placeholder] .ph-arrow .ph-arrow-label { display: inline-block; background: rgba(43, 43, 43, 0.92); color: rgb(255, 255, 255); font-style: normal; font-variant-caps: normal; font-weight: 600; font-width: normal; font-size: 0.95rem; line-height: 1.2; font-family: system-ui, sans-serif; font-size-adjust: none; font-kerning: auto; font-variant-alternates: normal; font-variant-ligatures: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-position: normal; font-variant-emoji: normal; font-feature-settings: normal; font-optical-sizing: auto; font-variation-settings: normal; padding: 0.4rem 0.65rem; border-radius: 10px; transform: rotate(-4deg); white-space: nowrap; box-shadow: rgba(43, 43, 43, 0.25) 0px 4px 0px; }[data-placeholder] .ph-arrow-label-wrap { position: absolute; left: 0px; top: 0px; transform: translate(-6%, -10%); }@keyframes ph-arrow-bob { 
  0%,100% { transform: translate(0px) rotate(0deg); }
  50% { transform: translate(-6px, -8px) rotate(-2deg); }
}@keyframes ph-arrow-draw { 
  100% { stroke-dashoffset: 0px; }
}@keyframes ph-arrow-out { 
  100% { opacity: 0; transform: translate(10px, 10px) scale(0.9); }
}@media (prefers-reduced-motion: reduce) {
  [data-placeholder] h1 .wave, [data-placeholder] .ph-arrow { animation: auto; }
  [data-placeholder] .ph-arrow .ph-arrow-stroke { stroke-dashoffset: 0px; }
}@media (max-width: 480px) {
  [data-placeholder] h1 { font-size: 2.4rem; }
  [data-placeholder] .ph-arrow { width: clamp(120px, 44vw, 180px); }
}
